-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- A part with a slide is routed a side action, but its time was not costed: the engine read no slide speed. The reference stages slideCycleRate
-- (100, Velocity) and the CAD engine measures each slide bundle's stroke. This calculator times the slides moving out and back once per shot, all
-- together, as 2 x the longest stroke / slideCycleRate (read as mm/s), per part (formula registry F-32, ASSUMED). A helper: no catalog operation
-- maps to it; the injection engine runs it for the routed side action and charges it at the press rate. Lifters add no time.
--
-- This migration creates one global calculator per spec entry (inputs are the
-- values the cost engine seeds, each shown with its source in the calculation
-- trace; calculated fields are the formulas the engine evaluates, it holds
-- none) and links every Plastic Molding catalog operation it computes to its
-- calculator in process_calculator_mappings.
--
-- Requires migration 804 (calculators.retired_at).
-- Self-contained, idempotent, post-checked.

BEGIN;

-- Injection Molding - Slide Movement
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Injection Molding - Slide Movement$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Injection Molding - Slide Movement$q$, 'process', 'single', false, true, true, $q$The time the hydraulic slides add to each shot, per part (formula registry F-32, ASSUMED: the reference gives the slide speed, slideCycleRate, not the motion): the slides move out and back once per shot, all together, so the longest slide stroke (the CAD SlideBundle stroke) twice over slideCycleRate (Velocity, read as mm/s), shared by the cavities. Lifters ride on the ejector stroke and add no time. A helper: the injection engine runs it for the routed side action and charges it at the press rate.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$The time the hydraulic slides add to each shot, per part (formula registry F-32, ASSUMED: the reference gives the slide speed, slideCycleRate, not the motion): the slides move out and back once per shot, all together, so the longest slide stroke (the CAD SlideBundle stroke) twice over slideCycleRate (Velocity, read as mm/s), shared by the cavities. Lifters ride on the ejector stroke and add no time. A helper: the injection engine runs it for the routed side action and charges it at the press rate.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Slide Stroke$q$, $q$Slide Stroke (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Slide Cycle Rate$q$, $q$Slide Cycle Rate (mm/s)$q$, $q$number$q$, $q$mm/s$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Cavities per Mold$q$, $q$Cavities per Mold$q$, $q$number$q$, $q$$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$floor(2 * {Slide Stroke} / {Slide Cycle Rate} / {Cavities per Mold} * 100 + 0.5) / 100$q$, 4, false);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Injection Molding - Slide Movement$q$, 4, 0)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
